-- NaCCA curriculum for Basic 6 (part 2 of 2): 185 indicators (Ghanaian Language, History, Mathematics, Religious & Moral Education, Science).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 6.
delete from public.curriculum_items
 where lower(class_name) = 'basic 6' and subject_key in ('ghanaian language', 'history', 'maths', 'rme', 'science');

